//! Compare actual cached glyphs with an independently generated JavaFX oracle.
#[cfg(windows)]
#[test]
#[ignore = "requires TOMATO_JAVA_GLYPH_ORACLE generated by the JavaFX font probe"]
fn cached_windows_glyphs_match_javafx_directwrite() -> Result<(), Box<dyn std::error::Error>> {
    let root = std::path::PathBuf::from(
        std::env::var_os("TOMATO_JAVA_GLYPH_ORACLE").ok_or("Missing JavaFX oracle")?,
    );
    let cases: Vec<serde_json::Value> =
        serde_json::from_slice(&std::fs::read(root.join("glyphs.json"))?)?;
    let ctx = egui::Context::default();
    ctx.set_theme(egui::Theme::Light);
    ctx.style_mut_of(egui::Theme::Light, |style| {
        style.visuals.text_options.lcd_subpixel = true;
        style.visuals.text_options.subpixel_binning = false;
    });
    let mut fonts = egui::FontDefinitions::empty();
    let mut data = egui::FontData::from_owned(std::fs::read("C:/Windows/Fonts/msyh.ttc")?);
    data.index = 1;
    data.tweak.subpixel_binning = Some(false);
    fonts.font_data.insert("java".into(), data.into());
    fonts
        .families
        .insert(egui::FontFamily::Proportional, vec!["java".into()]);
    ctx.set_fonts(fonts);
    let mut verified = 0;
    for dpi in [1., 1.25, 1.5, 2.] {
        let mut input = egui::RawInput::default();
        input
            .viewports
            .get_mut(&egui::ViewportId::ROOT)
            .unwrap()
            .native_pixels_per_point = Some(dpi);
        let mut glyphs = vec![];
        let mut output = ctx.run_ui(input, |ui| {
            for case in cases
                .iter()
                .filter(|case| case["dpi"].as_f64() == Some(f64::from(dpi)))
            {
                let c = char::from_u32(case["codepoint"].as_u64().unwrap() as u32).unwrap();
                let galley = ui.painter().layout_no_wrap(
                    c.to_string(),
                    egui::FontId::proportional(12.),
                    egui::Color32::BLACK,
                );
                glyphs.push((case, galley.rows[0].glyphs[0].uv_rect));
            }
        });
        output.textures_delta.clear();
        let atlas = ctx.fonts(|fonts| fonts.image());
        for (case, uv) in glyphs {
            let width = usize::from(uv.max[0] - uv.min[0]);
            let height = usize::from(uv.max[1] - uv.min[1]);
            assert_eq!(
                width,
                case["width"].as_u64().unwrap() as usize,
                "DPI {dpi}: {case}"
            );
            assert_eq!(
                height,
                case["height"].as_u64().unwrap() as usize,
                "DPI {dpi}: {case}"
            );
            assert_eq!(
                (uv.offset.x * dpi).round() as i64,
                case["x"].as_i64().unwrap(),
                "DPI {dpi}: horizontal ink origin"
            );
            let reference = std::fs::read(root.join(case["file"].as_str().unwrap()))?;
            let mut actual = Vec::with_capacity(width * height * 3);
            for y in 0..height {
                for x in 0..width {
                    let pixel = atlas[(usize::from(uv.min[0]) + x, usize::from(uv.min[1]) + y)];
                    actual.extend_from_slice(&[pixel.r(), pixel.g(), pixel.b()]);
                }
            }
            assert_eq!(
                actual, reference,
                "DPI {dpi}: actual atlas differs from JavaFX {case}"
            );
            verified += 1;
        }
    }
    assert!(verified >= 140);
    if let Some(path) = std::env::var_os("TOMATO_NATIVE_FONT_PROOF") {
        std::fs::write(
            path,
            serde_json::to_vec_pretty(
                &serde_json::json!({"status":"passed","glyphCases":verified,"scales":[1,1.25,1.5,2],"comparison":"exact RGB coverage, bounds and horizontal origin against independently generated JavaFX System font strikes","nativeScreenCapture":false}),
            )?,
        )?;
    }
    Ok(())
}
